import mongoose from 'mongoose';

const RatingSchema = new mongoose.Schema({
  audiobook: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Audiobook',
    required: true,
  },
  user: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User', // assuming you have a User model
    required: true,
  },
  rating: {
    type: Number,
    required: true,
    min: 1,
    max: 5,
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
});

// Optional: prevent a user from rating the same audiobook twice
RatingSchema.index({ audiobook: 1, user: 1 }, { unique: true });

export default mongoose.model('Rating', RatingSchema);
